namespace SmartEnum.Generators;

using Microsoft.CodeAnalysis;

[Generator(LanguageNames.CSharp)]
public sealed class SmartEnumAttributeGenerator : IIncrementalGenerator
{
	public void Initialize(IncrementalGeneratorInitializationContext context) => context
		.RegisterPostInitializationOutput(output => output.AddSource("SmartEnumAttribute.g.cs", """
				// <auto-generated />
				#nullable enable
				namespace SmartEnum;
				
				using System;

				[AttributeUsage(AttributeTargets.Class, Inherited = false, AllowMultiple = true)]
				internal sealed class SmartEnumAttribute<TKey> : Attribute
				{
					public string KeyName { get; }
					public FlatteningStrategy FlatteningStrategy { get; }
					public KeyValueOnBranchMissing KeyValueOnBranchMissing { get; }
					public SmartEnumAttribute(string keyName, FlatteningStrategy flatteningStrategy, KeyValueOnBranchMissing keyValueOnBranchMissing)
						=> (this.KeyName, this.FlatteningStrategy, this.KeyValueOnBranchMissing) = (keyName, flatteningStrategy, keyValueOnBranchMissing);
				}

				/// <summary>Controls the persistence shape: Flat combines branch data, Nested groups branch data into objects,
				/// and Separate gives each concrete variant its own complete model derived from a shared abstract flattened base.
				/// Separate models can be mapped with EF Core's table-per-concrete-type strategy.</summary>
				internal enum FlatteningStrategy { Flat, Nested, Separate }

				/// <summary>Controls a discriminator for a level absent from a concrete branch. SetNull makes that key nullable;
				/// PromptSubstitute requests a caller-provided fallback delegate. FirstBranch identifies the first discriminator
				/// level of an attribute group and is only valid on that group's first attribute.</summary>
				internal enum KeyValueOnBranchMissing { SetNull, PromptSubstitute, FirstBranch }

				/// <summary>Uses the named instance field as a property's storage during unvalidated transfer.
				/// The flattened property uses the public property's name and the field's type.</summary>
				[AttributeUsage(AttributeTargets.Property, Inherited = false)]
				internal sealed class SmartEnumPrivateAccessorAttribute : Attribute
				{
					public string AccessorFieldName { get; }
					public SmartEnumPrivateAccessorAttribute(string accessorFieldName) => this.AccessorFieldName = accessorFieldName;
				}

				/// <summary>Makes this property's transfer representation nullable. Reconstruction requests a fallback when
				/// a non-nullable domain value has no transfer value. Valid with every flattening strategy.</summary>
				[AttributeUsage(AttributeTargets.Property, Inherited = false)]
				internal sealed class SmartEnumNullablePropertyAttribute : Attribute { }

				/// <summary>Identifies the primary key used to link flattened structures. ForeignKeyName defaults to the property name.</summary>
				[AttributeUsage(AttributeTargets.Property, Inherited = false)]
				internal sealed class SmartEnumIdentityAttribute : Attribute
				{
					public string? ForeignKeyName { get; }
					public SmartEnumIdentityAttribute(string? foreignKeyName = null) => this.ForeignKeyName = foreignKeyName;
				}

				/// <summary>Marks a sealed owner of SmartEnum properties or collections for transfer model generation.</summary>
				[AttributeUsage(AttributeTargets.Class, Inherited = false)]
				internal sealed class SmartEnumParentAttribute : Attribute
				{
					public FlatteningStrategy FlatteningStrategy { get; }
					public SmartEnumParentAttribute(FlatteningStrategy flatteningStrategy) => this.FlatteningStrategy = flatteningStrategy;
				}

				/// <summary>Excludes state from generated constructors, factories and flattened data. Initialize it in user code.</summary>
				[AttributeUsage(AttributeTargets.Field | AttributeTargets.Property, Inherited = false)]
				internal sealed class SmartEnumIgnoreAttribute : Attribute { }

				"""));
}